/// Known top-level keys in `BivvyConfig`.
///
/// Used by [`check_unknown_keys`] to reject typos and unrecognized fields
/// that would otherwise be silently ignored by serde's `#[serde(default)]`.
const KNOWN_CONFIG_KEYS: &[&str] = &[
    "app_name",
    "settings",
    "template_sources",
    "steps",
    "workflows",
    "secrets",
    "extends",
    "requirements",
    "vars",
];

/// Reject unknown top-level keys in a config YAML value.
///
/// Because `BivvyConfig` uses `#[serde(default)]`, unrecognized keys
/// (often typos) are silently discarded and every field falls back to
/// its default. This function catches that case early.
///
/// Null / non-mapping values are allowed — they represent empty files
/// or scalar overrides handled elsewhere in the pipeline.
fn check_unknown_keys(value: &serde_yaml::Value, source_path: &Path) -> Result<()> {
    let mapping = match value.as_mapping() {
        Some(m) => m,
        None => return Ok(()),
    };

    let unknown: Vec<&str> = mapping
        .keys()
        .filter_map(|k| k.as_str())
        .filter(|k| !KNOWN_CONFIG_KEYS.contains(k))
        .collect();

    if unknown.is_empty() {
        Ok(())
    } else {
        Err(BivvyError::ConfigParseError {
            path: source_path.to_path_buf(),
            message: format!(
                "unknown config key{}: {}. Valid top-level keys: {}",
                if unknown.len() == 1 { "" } else { "s" },
                unknown.join(", "),
                KNOWN_CONFIG_KEYS.join(", ")
            ),
        })
    }
}

/// Parse YAML content into BivvyConfig.
///
/// Rejects unknown top-level keys before deserializing so that typos
/// surface as errors instead of silently falling back to defaults.
///
/// # Arguments
///
/// * `content` - The YAML content to parse
/// * `source_path` - Path for error reporting
pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
    let value: serde_yaml::Value =
        serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
            path: source_path.to_path_buf(),
            message: e.to_string(),
        })?;

    check_unknown_keys(&value, source_path)?;

    serde_yaml::from_value(value).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: e.to_string(),
    })
}

