+    #[test]
+    fn parse_config_rejects_unknown_top_level_keys() {
+        let content = "ap_name: MyApp\nsteps: {}";
+        let result = parse_config(content, Path::new("test.yml"));
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+
+        let err = result.unwrap_err();
+        let msg = err.to_string();
+        assert!(
+            msg.contains("ap_name"),
+            "error should mention the unknown key: {}",
+            msg
