+        fs::write(bivvy_dir.join("config.yml"), "app_name: Valid").unwrap();
+        fs::write(bivvy_dir.join("config.local.yml"), "settigns: {}").unwrap();
+
+        let result = load_merged_config(temp.path());
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+
+        let msg = result.unwrap_err().to_string();
+        assert!(msg.contains("settigns"), "should mention the typo: {}", msg);
+    }
