+/// its default. This function catches that case early.
+///
+/// Null / non-mapping values are allowed — they represent empty files
+/// or scalar overrides handled elsewhere in the pipeline.
+fn check_unknown_keys(value: &serde_yaml::Value, source_path: &Path) -> Result<()> {
+    let mapping = match value.as_mapping() {
+        Some(m) => m,
+        None => return Ok(()),
+    };
+
+    let unknown: Vec<&str> = mapping
+        .keys()
+        .filter_map(|k| k.as_str())
+        .filter(|k| !KNOWN_CONFIG_KEYS.contains(k))
+        .collect();
+
+    if unknown.is_empty() {
+        Ok(())
+    } else {
+        Err(BivvyError::ConfigParseError {
+            path: source_path.to_path_buf(),
+            message: format!(
+                "unknown config key{}: {}. Valid top-level keys: {}",
+                if unknown.len() == 1 { "" } else { "s" },
+                unknown.join(", "),
+                KNOWN_CONFIG_KEYS.join(", ")
+            ),
+        })
+    }
